<?php
require_once dirname(__DIR__).'/includes/functions.php';require_role(['student','counselor']);verify_csrf();$uid=(int)user()['id'];$quizId=(int)($_POST['quiz_id']??0);$stmt=$con->prepare('SELECT * FROM quizzes WHERE id=? AND is_active=1');$stmt->bind_param('i',$quizId);$stmt->execute();$quiz=$stmt->get_result()->fetch_assoc();if(!$quiz)json_response(['ok'=>false,'message'=>'Quiz not found.'],404);
$stmt=$con->prepare('SELECT * FROM quiz_questions WHERE quiz_id=?');$stmt->bind_param('i',$quizId);$stmt->execute();$questions=$stmt->get_result()->fetch_all(MYSQLI_ASSOC);$score=0;$max=0;$graded=[];foreach($questions as $q){$max+=(int)$q['points'];$selected=array_map('intval',(array)($_POST['answers'][$q['id']]??[]));$s=$con->prepare('SELECT id,is_correct FROM quiz_options WHERE question_id=?');$s->bind_param('i',$q['id']);$s->execute();$correct=[];foreach($s->get_result() as $o)if($o['is_correct'])$correct[]=(int)$o['id'];sort($selected);sort($correct);$ok=$selected===$correct;$pts=$ok?(int)$q['points']:0;$score+=$pts;$graded[]=[$q,$selected,$ok,$pts];}
$percent=$max?round($score/$max*100,2):0;$passed=$percent>=(float)$quiz['pass_score'];$con->begin_transaction();try{$stmt=$con->prepare('INSERT INTO quiz_attempts(user_id,quiz_id,score,max_score,passed,completed_at) VALUES(?,?,?,?,?,NOW())');$p=$passed?1:0;$stmt->bind_param('iiiii',$uid,$quizId,$score,$max,$p);$stmt->execute();$attempt=$con->insert_id;$ins=$con->prepare('INSERT INTO quiz_answers(attempt_id,question_id,selected_option_id,is_correct,points_earned) VALUES(?,?,?,?,?)');foreach($graded as [$q,$selected,$ok,$pts]){if(!$selected)$selected=[null];foreach($selected as $oid){$qid=(int)$q['id'];$good=$ok?1:0;$ins->bind_param('iiiii',$attempt,$qid,$oid,$good,$pts);$ins->execute();}}$con->commit();if($passed)award_badges($con,$uid);generate_recommendations($con,$uid);$_SESSION['quiz_result']=['title'=>$quiz['title'],'career_id'=>(int)$quiz['career_id'],'score'=>$score,'max'=>$max,'percent'=>$percent,'passed'=>$passed];json_response(['ok'=>true,'message'=>$passed?'Quiz passed!':'Quiz complete. Keep learning!','redirect'=>url('quiz/result.php')]);}catch(Throwable $e){$con->rollback();json_response(['ok'=>false,'message'=>'Could not grade the quiz.'],500);}
